/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import ElectrochemistryColors from "../../src/ElectrochemistryColors.js";
import { ElectrolysisScreen } from "../../src/electrolysis/ElectrolysisScreen.js";
import { GalvanicCellScreen } from "../../src/galvanic-cell/GalvanicCellScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { NernstScreen } from "../../src/nernst/NernstScreen.js";
import { ElectrochemistryPreferencesModel } from "../../src/preferences/ElectrochemistryPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from electrochemistryQueryParameters.
  const simPreferences = new ElectrochemistryPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new GalvanicCellScreen({
      name: stringManager.getScreenNames().galvanicCellStringProperty,
      tandem: Tandem.ROOT.createTandem("galvanicCellScreen"),
      conventionalCurrentProperty: simPreferences.conventionalCurrentProperty,
      backgroundColorProperty: ElectrochemistryColors.backgroundColorProperty,
    }),
    new NernstScreen({
      name: stringManager.getScreenNames().nernstStringProperty,
      tandem: Tandem.ROOT.createTandem("nernstScreen"),
      conventionalCurrentProperty: simPreferences.conventionalCurrentProperty,
      backgroundColorProperty: ElectrochemistryColors.backgroundColorProperty,
    }),
    new ElectrolysisScreen({
      name: stringManager.getScreenNames().electrolysisStringProperty,
      tandem: Tandem.ROOT.createTandem("electrolysisScreen"),
      conventionalCurrentProperty: simPreferences.conventionalCurrentProperty,
      backgroundColorProperty: ElectrochemistryColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { ElectrochemistryColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
